private interface ThrowingRunnable {
    void run() throws Exception;
}

/** Helper mimicking JUnit 5's assertDoesNotThrow for JUnit 4 tests. */
private static void assertDoesNotThrow(ThrowingRunnable executable, String message) {
    try {
        executable.run();
    } catch (Throwable t) {
        fail(message + ": " + t);
    }
}

