private JsonReader createReader() throws IOException {
    return new JsonReader(reader("{\"a\": \"android\", \"b\": \"banana\"}"));
}

private JsonReader readerAtStart() throws IOException {
    JsonReader r = createReader();
    r.beginObject();
    return r;
}

private JsonReader readerAfterFirstField() throws IOException {
    JsonReader r = readerAtStart();
    r.nextName();   // "a"
    r.nextString(); // "android"
    return r;
}

private JsonReader readerAfterBothFields() throws IOException {
    JsonReader r = readerAtStart();
    r.nextName();    // "a"
    r.nextString(); // "android"
    r.nextName();    // "b"
    r.nextString(); // "banana"
    return r;
}

