private static class SupportsCloneContext {
    final Document doc;
    final Element original;
    final Element clone;

    SupportsCloneContext(Document doc, Element original, Element clone) {
        this.doc = doc;
        this.original = original;
        this.clone = clone;
    }
}

private SupportsCloneContext setupSupportsClone() {
    Document doc = Jsoup.parse("<div class=foo>Text</div>");
    Element original = doc.select("div").first();
    Element clone = doc.clone().select("div").first();
    return new SupportsCloneContext(doc, original, clone);
}

@Test
public void testSupportsClone_preservesClass() {
    SupportsCloneContext ctx = setupSupportsClone();
    assertTrue("Original element should have class 'foo'", ctx.original.hasClass("foo"));
    assertTrue("Cloned element should retain class 'foo'", ctx.clone.hasClass("foo"));
}

@Test
public void testSupportsClone_preservesText() {
    SupportsCloneContext ctx = setupSupportsClone();
    assertEquals("Cloned element should retain original text", "Text", ctx.clone.text());
}

@Test
public void testSupportsClone_originalModificationDoesNotAffectClone() {
    SupportsCloneContext ctx = setupSupportsClone();
    ctx.original.removeClass("foo");
    ctx.original.text("None");

    assertFalse("Original element should no longer have class 'foo'", ctx.original.hasClass("foo"));
    assertTrue("Cloned element should still have class 'foo'", ctx.clone.hasClass("foo"));
    assertEquals("Original element text should be updated to 'None'", "None", ctx.original.text());
    assertEquals("Cloned element text should remain unchanged as 'Text'", "Text", ctx.clone.text());
}

