public void testNewsHomepage(@TempDir File tempDir) throws IOException {
    // Obtain the resource file from the classpath
    File source = getFile("/htmltests/news-com-au-home.html");
    // Verify that the resource file actually exists
    assertTrue(source.exists(), "Source HTML file must exist before parsing");

    // Copy the resource into the injected temporary directory
    File in = new File(tempDir, source.getName());
    Files.copy(source.toPath(), in.toPath());

    // Parse the copied file
    Document doc = Jsoup.parse(in, "UTF-8", "http://www.news.com.au/");

    // Assertions with clear, descriptive messages
    assertEquals(
            "News.com.au | News from Australia and around the world online | NewsComAu",
            doc.title(),
            "Document title should match the expected value"
    );
    assertEquals(
            "Brace yourself for Metro meltdown",
            doc.select(".id1225817868581 h4").text().trim(),
            "Headline text should match the expected value"
    );

    Element a = doc.select("a[href=/entertainment/horoscopes]").first();
    assertNotNull(a, "Anchor element for '/entertainment/horoscopes' should be present");
    assertEquals(
            "/entertainment/horoscopes",
            a.attr("href"),
            "Href attribute should be the expected relative path"
    );
    assertEquals(
            "http://www.news.com.au/entertainment/horoscopes",
            a.attr("abs:href"),
            "Absolute href should be correctly resolved"
    );

    Element hs = doc.select("a[href*=naughty-corners-are-a-bad-idea]").first();
    assertNotNull(hs, "Anchor element containing 'naughty-corners-are-a-bad-idea' should be present");
    assertEquals(
            "http://www.heraldsun.com.au/news/naughty-corners-are-a-bad-idea-for-kids/story-e6frf7jo-1225817899003",
            hs.attr("href"),
            "Href should match the expected external URL"
    );
    assertEquals(
            hs.attr("href"),
            hs.attr("abs:href"),
            "For external links, absolute href should be identical to href"
    );
}

