    return doc.selectFirst("table tbody tr");
}

// Refactored tests
@Test
public void testKeepsPreTextAtDepth_Text() {
    Document doc = setupTestKeepsPreTextAtDepth();
    assertEquals("Document text should preserve the pre‑formatted code block", "code\n\ncode", doc.text());
}

@Test
public void testKeepsPreTextAtDepth_Html() {
    Document doc = setupTestKeepsPreTextAtDepth();
    assertEquals("HTML output should match the original markup exactly", "<pre><code><span><b>code\n\ncode</b></span></code></pre>", doc.body().html());
}

@Test
public void testChildSizeWithMixedContent_ChildrenSize() {
    Element row = setupTestChildSizeWithMixedContent();
    assertEquals("Row should have 2 child elements (td)", 2, row.childrenSize());
}

@Test
public void testChildSizeWithMixedContent_ChildNodeSize() {
    Element row = setupTestChildSizeWithMixedContent();
    assertEquals("Row should have 5 child nodes (including text nodes)", 5, row.childNodeSize());
}

