// New shared fixtures
private static final Document PRE_DOC = Jsoup.parse(
        "<pre><code><span><b>code\n\ncode</b></span></code></pre>"
);

private static final Element TABLE_ROW = Jsoup.parse(
        "<table><tbody>\n<tr>\n<td>15:00</td>\n<td>sport</td>\n</tr>\n</tbody></table>"
).selectFirst("table tbody tr");

// Refactored tests for pre‑formatted text handling
@Test
public void testKeepsPreTextAtDepth_Text() {
    assertEquals(
            "Document text should preserve the pre‑formatted code block",
            "code\n\ncode",
            PRE_DOC.text()
    );
}

@Test
public void testKeepsPreTextAtDepth_Html() {
    assertEquals(
            "HTML output should match the original markup exactly",
            "<pre><code><span><b>code\n\ncode</b></span></code></pre>",
            PRE_DOC.body().html()
    );
}

// Refactored tests for mixed content child size
@Test
public void testChildSizeWithMixedContent_ChildrenSize() {
    assertEquals(
            "Row should have 2 child elements (td)",
            2,
            TABLE_ROW.childrenSize()
    );
}

@Test
public void testChildSizeWithMixedContent_ChildNodeSize() {
    assertEquals(
            "Row should have 5 child nodes (including text nodes)",
            5,
            TABLE_ROW.childNodeSize()
    );
}

